from src.masker import mask_phone


def log_message(message):
    return mask_phone(message)


def log_event(event, message, level='INFO', timestamp=None):
    return {
        'event': event,
        'message': mask_phone(message),
        'level': level,
        'timestamp': timestamp,
    }

import re


_PHONE_PATTERN = re.compile(r'(?<!\d)(01[016789]|02|0[3-6][1-5]|0[7-9][0-9])-?\d{3,4}-?\d{4}(?!\d)')


def mask_phone(text):
    def _mask(match):
        phone = match.group(0)
        digits = re.sub(r'\D', '', phone)
        if len(digits) < 10:
            return phone
        if len(digits) == 10:
            return digits[:6] + '****'
        return digits[:7] + '****'

    return _PHONE_PATTERN.sub(_mask, text)

