import re

# 국내 전화번호에서 가운데 네 자리를 가립니다.
# 숫자가 붙어 있는 경우는 경계로 보지 않으므로 마스킹하지 않습니다.
_PHONE_PATTERN = re.compile(r'(?<!\d)(01\d)-(?P<middle>\d{3,4})-(?P<last>\d{4})(?!\d)')


def mask_phone(text):
    return _PHONE_PATTERN.sub(lambda m: f"{m.group(1)}-****-{m.group('last')}", text)

